import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-hitl-brownfield-insert/OrderFulfillmentBpmn/OrderFulfillmentBpmn.bpmn')
root = tree.getroot()
ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

# Collect all declared ids
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

errors = []

# Check all sourceRef/targetRef resolve
for sf in root.findall('.//bpmn:sequenceFlow', ns):
    for attr in ('sourceRef', 'targetRef'):
        v = sf.get(attr)
        if v not in all_ids:
            errors.append(f'sequenceFlow {sf.get(\"id\")}: {attr}={v} unresolved')

# Check all bpmnElement refs in diagram resolve
for shape in root.findall('.//bpmndi:BPMNShape', {'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI'}):
    v = shape.get('bpmnElement')
    if v not in all_ids:
        errors.append(f'BPMNShape {shape.get(\"id\")}: bpmnElement={v} unresolved')
for edge in root.findall('.//bpmndi:BPMNEdge', {'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI'}):
    v = edge.get('bpmnElement')
    if v not in all_ids:
        errors.append(f'BPMNEdge {edge.get(\"id\")}: bpmnElement={v} unresolved')

# Check incoming/outgoing refs resolve
proc = root.find('bpmn:process', ns)
for el in proc:
    for child in el:
        tag = child.tag.split('}')[-1]
        if tag in ('incoming', 'outgoing'):
            if child.text.strip() not in all_ids:
                errors.append(f'{el.get(\"id\")}: {tag}={child.text.strip()} unresolved')

# Check every flow node has a shape
flow_node_ids = set()
for el in proc:
    tag = el.tag.split('}')[-1]
    if tag not in ('sequenceFlow', 'extensionElements'):
        flow_node_ids.add(el.get('id'))

shape_refs = {s.get('bpmnElement') for s in root.findall('.//{http://www.omg.org/spec/BPMN/20100524/DI}BPMNShape')}
for nid in flow_node_ids:
    if nid not in shape_refs:
        errors.append(f'Node {nid} has no BPMNShape')

# Check every flow has an edge
flow_ids = {sf.get('id') for sf in proc.findall('bpmn:sequenceFlow', ns)}
edge_refs = {e.get('bpmnElement') for e in root.findall('.//{http://www.omg.org/spec/BPMN/20100524/DI}BPMNEdge')}
for fid in flow_ids:
    if fid not in edge_refs:
        errors.append(f'SequenceFlow {fid} has no BPMNEdge')

if errors:
    for e in errors: print('ERROR:', e)
else:
    print('STRUCTURAL CHECK: PASS')
"
